//************************************************************************************************
/* 空调以外设备发码规则：结合每个设备的数据表和索引表,按一个键发一组数据,如下：(共10个Ｂ,数据均为十六进制),: */
/* 要结合后面的 品牌索引说明发送数据 */
/* 0x30+0x00+F_code(1B)+KEY_code(2B)+COM_CODE(4B)+CHECKSUM */
/* 0x30 0x00：固定 */
/* F_code(1B)：对应每一组数据的第一个数据：如IPTV：第0组：0x01, */
/* KEY_code(2B):对应按键数据,两个字节,见对对应设备数据表：如IPTV：第2组：电源这个键：0x0f,0xf0; 静音键是：0x4e,0xb1 */
/* COM_CODE(4B)：对应每一组最后四个字节：如IPTV第2组：0x01,0xfe,0x00,0x00  (数据表第三行,最后四个字节)*/
/* CHECKSUM：所得数据和的低8位,发送方自行处理 */
/*   范例：正常发送(连续的发,十六进制) 0x30,0x00,0x01,0x0f,0xf0,0x01,0xfe,0x00,0x00,0x2F */
//************************************************************************************************
#ifndef UINT8
typedef unsigned char  UINT8;
#endif

#ifndef UINT16
typedef unsigned short UINT16;
#endif

#ifndef BYTE
typedef unsigned char BYTE;
#endif

#ifndef U16
typedef unsigned short U16;
#endif

#ifndef kal_uint8
typedef unsigned char kal_uint8;
#endif

#ifndef U8
typedef unsigned char U8;
#endif

typedef struct
{
    U8 format_index;
    U8 keytable[50];
    U8 custome_code[4];
}remote_IPTV_data_struct; /*IPTV， 网络机顶盒*/


typedef struct
{
    U8 format_index;
    U8 keytable[52];
    U8 custome_code[4];
}remote_tv_data_struct; /*电视机*/

typedef struct
{
    U8 ARCFIXCODLEN;
    U8 ARCFIXCODE[78];

}remote_arc_data_struct;        /*空调*/


